# OpenEVV sound map: Chinese (Mandarin, latin as English) (eSpeak NG voice sit/cmn), spoken by openevv's German module
# with the sounds, the melody and the tones of the language itself.
# Written by engine/accent/mapwriter.py; OpenEvvFrontend reads it, and docs/LANGUAGES.md
# says what each line means. Edit freely: the file is read each time a voice starts.

template dedx
style standard
vowels i I e E a A u U o O y Y oe OE @ aj aw oj a~ E~ o~ oe~ E: R
glides j w
schwa @
secondary 2
words apart
onset 2

# the melody: tone; a question that wants yes or no: rise
accent f0=own range=120 level=30 decl=6 declmax=25 lag=70 lead=15 fs=-6 fq=6 qreg=18 fc=4 fe=0 fw=-4 span=1 stressed=88 weak=112 stop=1

# the tones, under eSpeak NG's names for them
tone 55 p=0:48,100:50
tone 35 p=0:31,30:29,100:50 dur=106
tone 214 p=0:23,45:10,100:38 dur=125 creak=40 cfrom=30 cto=65
tone 21 p=0:23,65:11,100:10 dur=92 creak=25 cfrom=55 cto=100
tone 51 p=0:50,12:52,100:12 dur=90
tone 53 p=0:50,12:52,100:30 dur=85
tone 11 p=0:22,100:12 dur=62 weak=75 av=-3
tone 22 p=0:32,100:22 dur=62 weak=75 av=-3
tone 33 p=0:36,100:30 dur=62 weak=75 av=-3
tone 44 p=0:30,100:40 dur=62 weak=75 av=-3
weaktones 11 22 33 44

# what the module says in place of a phone it is given
says C t S
says J d Z
says P p f
says T t s

